// 1. Access Feature Layer
var fs = FeatureSetByPortalItem(
    Portal("https://beta-inc.maps.arcgis.com"), 
    "e1ef72adca7846e2af2be1a6fce40bbf", 
    0, 
    ["OBJECTID", "Current_RSR", "Projected_RSR", "CIP_Treatment_Year"], 
    false
);

var features = [];
var idCounter = 1;
var inspectYear = 2025;

for (var f in fs) {
    var roadID = DefaultValue(f.OBJECTID, idCounter);
    var baseRSR = Number(DefaultValue(f.Current_RSR, 0));
    var newRSR = Number(DefaultValue(f.Projected_RSR, baseRSR));
    
    // 2. Safe string-to-number conversion for CIP Year
    var rawYearStr = f.CIP_Treatment_Year;
    var treatYear = null;
    
    if (!IsEmpty(rawYearStr)) {
        var numYear = Number(rawYearStr);
        if (!IsEmpty(numYear) && numYear > 0) {
            treatYear = numYear;
        }
    }

    // 3. Generate 6 records per road segment (2025-2030)
    for (var planYr = 2025; planYr <= 2030; planYr++) {
        var projRSR = 0;
        
        // Scenario A: Untreated / Null CIP Year OR Plan Year is prior to scheduled treatment
        if (IsEmpty(treatYear) || planYr < treatYear) {
            var yearsDegraded = planYr - inspectYear;
            projRSR = Max([baseRSR - (yearsDegraded * 2), 0]);
        } 
        // Scenario B: CIP Treatment applied on or before current Plan Year
        else {
            var yearsPostTreatment = planYr - treatYear;
            projRSR = Max([newRSR - (yearsPostTreatment * 2), 0]);
        }

        // Key Fix: Bind the filtering year directly to the output schema
        // If treated, match treatYear; if untreated/null, match the active planYr slice
        var activeGroupYear = planYr;
        if (!IsEmpty(treatYear)) {activeGroupYear = treatYear;
        }

        Push(features, {
            'attributes': {
                'OBJECTID': idCounter,
                'Road_ID': Number(roadID),
                'Plan_Year': Number(planYr),
                'Chart_Group_Year': Number(activeGroupYear),
                'Projected_RSR_Degraded': Round(Number(projRSR), 2)
            }
        });
        idCounter++;
    }
}

// 4. Schema definition for Experience Builder Data Engine
var dict = {
  'fields': [
    {'name': 'OBJECTID', 'type': 'esriFieldTypeOID', 'alias': 'OBJECTID'},
    {'name': 'Road_ID', 'type': 'esriFieldTypeInteger', 'alias': 'Road_ID'},
    {'name': 'Plan_Year', 'type': 'esriFieldTypeInteger', 'alias': 'Plan_Year'},
    {'name': 'Chart_Group_Year', 'type': 'esriFieldTypeInteger', 'alias': 'Chart_Group_Year'},
    {'name': 'Projected_RSR_Degraded', 'type': 'esriFieldTypeDouble', 'alias': 'Projected_RSR_Degraded'}
  ],
  'objectIdField': 'OBJECTID',
  'geometryType': '',
  'features': features
};

return FeatureSet(dict);
